test('bundled pack changes are visible in a collapsed pre-update summary without catalog access',{timeout:30000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..')),browser=await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']}),page=await browser.newPage();
 try{await page.goto(server.url);await page.locator('.game-tile').first().waitFor();await page.evaluate(()=>{const installed=PlayroomPacks.list().find(p=>p.id==='mage-brawl');window.PlayroomPWA={...PlayroomPWA,updateInfo:{version:'99.0.0',releases:[{version:'99.0.0',changes:['App change']}],download:{phase:'available'},packs:[{id:installed.id,version:'99.0.0',name:'Стихийная потасовка',releases:[{version:'99.0.0',changes:['Pack change before update']}]}]}};const button=document.createElement('button');button.dataset.command='show-updates';document.body.append(button);button.click();button.remove();});const details=page.locator('.updates-modal .update-pack-changes');assert.equal(await details.getAttribute('open'),null);await details.locator('summary').click();assert(await details.getByText('Pack change before update',{exact:true}).isVisible());assert.equal(await page.locator('.updates-modal [data-command=update-packs]').count(),0);assert(await page.locator('.updates-modal [data-command=update-all]').isVisible());
 }finally{await browser.close();await server.close();}
});

test('update all permits a dismissed unused local lobby but still blocks live rooms',{timeout:60000},async()=>{
 const root=path.resolve(__dirname,'..'),server=await serveBrowserFixture(root),engine=process.env.LAB_ENGINE==='webkit'?require('playwright-core').webkit:chromium,browser=await engine.launch(process.env.LAB_ENGINE==='webkit'?{headless:true}:{headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']}),context=await browser.newContext({viewport:{width:390,height:844},hasTouch:true,isMobile:true,reducedMotion:'reduce'}),errors=[];
 const counts=await require('./account-sync-fixture.cjs').installFetch(context,route=>route.fulfill({json:{}}));
 await context.addInitScript(()=>{localStorage.setItem('playroom.player-profile.v1',JSON.stringify({version:1,id:'update-idle-owner',name:'Тест'}));localStorage.setItem('playroom.settings.v1',JSON.stringify({sound:false,tutorialsEnabled:false}));});const page=await context.newPage(),active=()=>page.locator('#modal-root>[data-surface-state=active]');page.setDefaultTimeout(7000);page.on('pageerror',e=>errors.push(e.message));
 try{
  if(process.env.PLAYROOM_TEST_ARTIFACT)await page.route(server.url,route=>route.fulfill({contentType:'text/html',body:require('fs').readFileSync(process.env.PLAYROOM_TEST_ARTIFACT)}));
  await page.goto(server.url);await page.locator('[data-start=uno]').first().tap();await active().locator('[data-game-mode=hotseat]').tap();await active().locator('.room-v021').waitFor();
  await active().locator('.modal-head [data-command=close-modal]').tap();if(await active().count())await active().locator('.modal-head [data-command=close-modal]').tap();
  await page.locator('[data-hub-page=sessions]').tap();assert.match(await page.locator('#hub-sessions-page').innerText(),/Нет активных партий/);
  await page.evaluate(()=>{window.updateProbe={download:0,activate:0};window.PlayroomPWA={...PlayroomPWA,updateInfo:{version:'99.0.0',releases:[],download:{phase:'available'}},downloadUpdate:async()=>{updateProbe.download++;},activateUpdate:async()=>{updateProbe.activate++;}};});
  await page.locator('[data-hub-page=profile]').tap();await page.locator('#hub-profile-page [data-command=show-updates]').tap();await active().locator('[data-command=update-all]').tap();
  await page.waitForFunction(()=>!PlayroomUnifiedUpdateBusy);const result=await page.evaluate(()=>({probe:updateProbe,status:document.querySelector('[data-update-status]')?.textContent,room:PlayroomAppBridge.room()?.phase}));
  if(process.env.PLAYROOM_CAPTURE_DIR){require('fs').mkdirSync(process.env.PLAYROOM_CAPTURE_DIR,{recursive:true});await page.screenshot({path:path.join(process.env.PLAYROOM_CAPTURE_DIR,'update-unused-lobby.png')});}
  assert.deepEqual(result.probe,{download:1,activate:1},JSON.stringify(result));assert.equal(await page.evaluate(()=>PlayroomAppBridge.room()),null,'unused room is retired before pack cleanup');
  // Alternative to reloading a persisted live game: isolate the network port
  // while still at the hub, then restore it before the real local-game case.
  await page.evaluate(()=>{window.originalUpdateNetwork=PlayroomNetworkLibrary;window.PlayroomNetworkLibrary={...PlayroomNetworkLibrary,hasActiveRoom:()=>true};});await active().locator('[data-command=update-all]').tap();await page.waitForFunction(()=>!PlayroomUnifiedUpdateBusy);assert.deepEqual(await page.evaluate(()=>updateProbe),{download:1,activate:1},'active network context remains blocked');assert.match(await active().locator('[data-update-status]').innerText(),/после выхода/);await page.evaluate(()=>{window.PlayroomNetworkLibrary=originalUpdateNetwork;delete window.originalUpdateNetwork;});
  await page.evaluate(()=>PlayroomAppBridge.closeModal(true));await page.locator('[data-hub-page=games]').tap();await page.locator('[data-start=uno]').first().tap();await active().locator('[data-game-mode=hotseat]').tap();await active().locator('[data-command=lobby-start]').tap();await page.locator('.table-shell').waitFor();const liveId=await page.evaluate(()=>PlayroomAppBridge.room().id);
  await page.evaluate(()=>{const button=document.createElement('button');button.dataset.command='show-updates';document.body.append(button);button.click();button.remove();});await active().locator('[data-command=update-all]').tap();await page.waitForFunction(()=>!PlayroomUnifiedUpdateBusy);
  assert.deepEqual(await page.evaluate(()=>updateProbe),{download:1,activate:1},'a started local game still blocks activation');assert.equal(await page.evaluate(()=>PlayroomAppBridge.room().id),liveId);assert.match(await active().locator('[data-update-status]').innerText(),/после выхода/);
  assert.deepEqual(errors,[]);assert.equal(counts.nativeSupabaseRequests,0);
 }finally{await context.close();await browser.close();await server.close();}
});
